set -euo pipefail
cd /home/ubuntu/apps/travel-planner
sha256sum rag/retrieval/search_chunks.py rag/eval/cases/eval_questions.jsonl
export PYTHONPATH=rag
.venv/bin/python - <<'PY'
import json
from pathlib import Path
from retrieval.search_chunks import require_database_url
import psycopg
with psycopg.connect(require_database_url()) as conn:
    names = [r[0] for r in conn.execute('SELECT DISTINCT name FROM v2.attractions ORDER BY name')]
Path('/tmp/travel_catalog_names.json').write_text(json.dumps(names, ensure_ascii=False), encoding='utf-8')
PY
echo  | base64 -d > /tmp/travel_audit_retrieval.py
.venv/bin/python /tmp/travel_audit_retrieval.py --questions rag/eval/cases/eval_questions.jsonl --catalog /tmp/travel_catalog_names.json --output /tmp/travel_retrieval_audit.json
